import { randomUUID } from "node:crypto";
import { existsSync, readFileSync, rmSync, unlinkSync, writeFileSync, } from "node:fs";
import path from "node:path";
import { afterEach, beforeEach, describe, expect, it, vi, } from "vitest";
import { NO_GITHUB, OLD_CONFIG, PREFIX, PUSH_CONDITION, PUSH_SUBJECT, REPLAY_COMMAND_ENV, SDK_LANGUAGE_ENV, WORKFLOW, } from "./constants.js";
import { githubRunIdentity, localClient } from "./github.js";
import { cleanup, reportSteps, runCli, stateDirectory } from "./local.js";
import { CommandError, deps, GithubUnreachable, ValueError, } from "./runtime.js";
import { CloudFixture, capture, ID, KEY_ID, KEY_WORKFLOW, LOCAL_CLIENT, OIDC_TOKEN, PUSH_WORKFLOW, RUN, RUNNER_CLIENT, registryPrinting, restoreDeps, stub, TOKEN, WORKFLOW_TEXT, withEnv, } from "./testFixture.js";
import { initialize, toYaml, updateWorkflow } from "./workflow.js";
import { startsOnPush } from "./workflowText.js";
const REAL_COMMAND = deps.command;
const WORKFLOW_PATH = ".github/workflows/bitfab-replay.yml";
let fixture;
beforeEach(() => {
    fixture = new CloudFixture();
});
afterEach(() => {
    fixture.dispose();
});
async function withLocal(extra, work) {
    fixture.local(extra);
    try {
        return await work();
    }
    finally {
        restoreDeps();
    }
}
async function initializeIn(argv = [], { language, directory } = {}) {
    const savedCwd = process.cwd();
    const savedRoot = deps.rootDirectory;
    deps.rootDirectory = () => fixture.root;
    process.chdir(directory ?? fixture.root);
    try {
        return await withEnv({ [SDK_LANGUAGE_ENV]: language || undefined }, () => initialize(argv));
    }
    finally {
        process.chdir(savedCwd);
        deps.rootDirectory = savedRoot;
    }
}
function freshSetup() {
    const workflow = path.join(fixture.root, WORKFLOW_PATH);
    if (existsSync(workflow)) {
        unlinkSync(workflow);
    }
}
function fakeGh(calls, failure = null) {
    return (args, options = {}) => {
        if (args[0] !== "gh") {
            return REAL_COMMAND(args, options);
        }
        calls.push([args, options]);
        if (failure !== null) {
            throw failure;
        }
        return "";
    };
}
async function submitWithoutGithub(extra = [], { workflow, execution = ID, mocks = {} } = {}) {
    fixture.write(WORKFLOW_PATH, workflow ?? PUSH_WORKFLOW);
    const chosen = {
        githubAccess: () => {
            throw new ValueError(NO_GITHUB);
        },
        api: () => undefined,
        ...mocks,
    };
    return await withLocal(chosen, async () => {
        const api = deps.api;
        const { value, stderr } = await capture(async () => {
            try {
                const [record, found] = await runCli([
                    ...fixture.replay,
                    "--cloud",
                    "--cloud-request-id",
                    execution,
                    ...extra,
                ]);
                return { record, found };
            }
            catch (error) {
                if (error instanceof ValueError) {
                    return { record: error, found: null };
                }
                throw error;
            }
        });
        return { ...value, api, err: stderr };
    });
}
function remoteBranch() {
    return fixture.git("ls-remote", "origin", `refs/heads/${PREFIX}${ID}`);
}
function savedState() {
    return JSON.parse(readFileSync(path.join(stateDirectory(fixture.root), `${ID}.json`), "utf8"));
}
async function keyedDispatch({ client = LOCAL_CLIENT, issued, failure, } = {}) {
    fixture.write(WORKFLOW_PATH, KEY_WORKFLOW);
    const record = {};
    const calls = [];
    const bitfab = vi.fn(() => {
        if (failure !== undefined) {
            throw failure;
        }
        return issued === undefined ? { token: TOKEN } : issued;
    });
    const { stderr } = await withLocal({
        preflight: async () => { },
        api: fixture.github(record, "", null, calls),
        localClient: () => client,
        bitfabApi: bitfab,
    }, () => capture(() => runCli([...fixture.argv, "--cloud-detach"])));
    const dispatch = calls.find(([suffix]) => suffix.endsWith("dispatches"))?.[1];
    return {
        inputs: dispatch.payload.inputs,
        bitfab,
        saved: savedState(),
        err: stderr,
    };
}
function keyRegistry() {
    fixture.write("registry.mjs", `import { writeFileSync } from "node:fs"\nwriteFileSync(process.env.MARK, process.env.BITFAB_REPLAY_BITFAB_API_KEY ?? "")\nprocess.stdout.write(${JSON.stringify(`${JSON.stringify({ testRunId: RUN, items: [] })}\n`)})\n`);
    fixture.commit();
    return path.join(fixture.temp, "key");
}
async function executeWithToken(mark, bitfab, { client = RUNNER_CLIENT, identity = true, } = {}) {
    const event = path.join(fixture.temp, "event.json");
    writeFileSync(event, JSON.stringify({ inputs: { key_id: TOKEN } }));
    stub("localClient", () => client);
    stub("bitfabApi", bitfab);
    stub("urlopen", async () => Buffer.from(JSON.stringify({ value: OIDC_TOKEN })));
    try {
        await fixture.execute(null, {
            MARK: mark,
            GITHUB_EVENT_PATH: event,
            BITFAB_REPLAY_BITFAB_API_KEY: "",
            ACTIONS_ID_TOKEN_REQUEST_URL: identity ? "https://token.example/id" : "",
            ACTIONS_ID_TOKEN_REQUEST_TOKEN: identity ? "request-bearer" : "",
        });
    }
    finally {
        restoreDeps();
    }
}
describe("cloud replay workflow setup", () => {
    it("init finds the lockfile pnpm and ruby versions the runner needs", async () => {
        const cases = [
            [
                "typescript",
                { "web/package-lock.json": "", "web/package.json": "{}" },
                "web",
                ["cache: npm", "cache-dependency-path: web/package-lock.json"],
                [],
            ],
            [
                "typescript",
                { "pnpm-lock.yaml": "lockfileVersion: '6.0'\n", "package.json": "{}" },
                ".",
                ['version: "8"', "cache: pnpm"],
                ["cache-dependency-path"],
            ],
            [
                "typescript",
                {
                    "web/pnpm-lock.yaml": "lockfileVersion: '9.0'\n",
                    "web/package.json": '{"packageManager": "pnpm@9.15.0"}',
                },
                "web",
                ["package_json_file: web/package.json"],
                ["          version:"],
            ],
            ["ruby", { Gemfile: "" }, ".", ["ruby-version: ruby"], []],
            [
                "ruby",
                { Gemfile: "", ".ruby-version": "3.3.6\n" },
                ".",
                [],
                ["ruby-version"],
            ],
            [
                "ruby",
                { "app/Gemfile": "", ".tool-versions": "nodejs 22\nruby 3.4.1\n" },
                "app",
                ['ruby-version: "3.4.1"', "working-directory: app"],
                [],
            ],
        ];
        for (const [language, files, directory, present, absent] of cases) {
            freshSetup();
            for (const [name, content] of Object.entries(files)) {
                fixture.write(name, content);
            }
            await initializeIn([], {
                language,
                directory: path.join(fixture.root, directory),
            });
            const text = fixture.read(WORKFLOW_PATH);
            for (const expected of present) {
                expect(text, JSON.stringify(files)).toContain(expected);
            }
            for (const unexpected of absent) {
                expect(text, JSON.stringify(files)).not.toContain(unexpected);
            }
            for (const name of Object.keys(files)) {
                unlinkSync(path.join(fixture.root, name));
            }
        }
    });
    it("init finds the go program that starts cloud replay", async () => {
        freshSetup();
        fixture.write("go.mod", "module x\n");
        fixture.write("lib/lib.go", "package lib\n\nfunc X() { RunCloudReplayCLI() }\n");
        const missing = initializeIn([], { language: "go" });
        await expect(missing).rejects.toThrow(ValueError);
        await expect(missing).rejects.toThrow(/--run/);
        fixture.write("cmd/registry/main.go", "package main\n\nfunc main() { bitfab.RunCloudReplayCLI(ctx, os.Args[1:], os.Stdout, os.Stderr) }\n");
        fixture.write("cmd/registry/main_test.go", "package main\n\nfunc T() { RunCloudReplayCLI() }\n");
        await initializeIn([], { language: "go" });
        const text = fixture.read(WORKFLOW_PATH);
        expect(text).toContain("go-version-file: go.mod");
        expect(text).toContain("run: go run ./cmd/registry --cloud-execute");
        freshSetup();
        await initializeIn(["--run", "go run ./other"], { language: "go" });
        expect(fixture.read(WORKFLOW_PATH)).toContain("run: go run ./other --cloud-execute");
    });
    it("init validates names and prefix", async () => {
        freshSetup();
        fixture.write("package.json", "{}");
        for (const [argv, message] of [
            [["--secret-prefix", "lower_"], /uppercase/],
            [["--secret-prefix", "NOUNDERSCORE"], /uppercase/],
            [["--secret", "lower"], /uppercase/],
        ]) {
            const attempt = initializeIn(argv, { language: "typescript" });
            await expect(attempt).rejects.toThrow(ValueError);
            await expect(attempt).rejects.toThrow(message);
        }
        await initializeIn(["--secret-prefix", "", "--secret", "OPENAI_API_KEY"], {
            language: "typescript",
        });
        expect(fixture.read(WORKFLOW_PATH)).toContain(`OPENAI_API_KEY: "\${{ secrets.OPENAI_API_KEY }}"`);
    });
    it("init refuses a setup from an older sdk", async () => {
        fixture.write(OLD_CONFIG, "{}");
        const attempt = initializeIn([], { language: "typescript" });
        await expect(attempt).rejects.toThrow(ValueError);
        await expect(attempt).rejects.toThrow(/Delete \.bitfab\/cloud\.json/);
    });
    it("yaml quotes keys that would change meaning", () => {
        const text = toYaml({
            on: { push: {} },
            "a: b": 1,
            "# note": "x",
            yes: true,
            "runs-on": "linux",
        });
        expect(text).toContain("on:\n");
        expect(text).toContain('"a: b": 1\n');
        expect(text).toContain('"# note": x\n');
        expect(text).toContain('"yes": true\n');
        expect(text).toContain("runs-on: linux\n");
    });
});
describe("cloud replay without GitHub access", () => {
    it("without github access a replay starts on push and warns", async () => {
        const { record, found, api, err } = await submitWithoutGithub();
        expect(found).toBeNull();
        expect(api).not.toHaveBeenCalled();
        expect(record.state).toBe("dispatch_unknown");
        expect(record.startedOnPush).toBe(true);
        expect(remoteBranch().split(/\s+/)[0]).toBe(record.sha);
        expect(fixture
            .git("log", "-1", "--format=%s", record.sha)
            .startsWith(PUSH_SUBJECT)).toBe(true);
        expect(err).toContain("this command gets no updates on it: Cloud replay needs");
        expect(err).toContain("BITFAB_API_KEY secret");
        expect(err).toContain(`https://github.com/acme/app/actions/workflows/${WORKFLOW}`);
        expect(err).toContain(`git push origin --delete ${PREFIX}${ID}`);
        expect(savedState()).not.toHaveProperty("unfollowed");
        const again = await submitWithoutGithub();
        expect(again.api).not.toHaveBeenCalled();
        expect(again.record.sha).toBe(record.sha);
    });
    it("without github access a workflow that never starts on push says how to fix it", async () => {
        const { record: error } = await submitWithoutGithub([], {
            workflow: KEY_WORKFLOW,
        });
        expect(error).toBeInstanceOf(ValueError);
        expect(String(error.message)).toMatch(/Cloud replay needs access to GitHub.*run bitfab-replay --cloud-update/);
        expect(remoteBranch()).toBe("");
    });
    it("without github access options that need a private repository are refused", async () => {
        fixture.write("cert.pem", "test\n");
        for (const [extra, flag] of [
            [["--cloud-full-output"], "--cloud-full-output"],
            [["--cloud-allow-file", "cert.pem"], "--cloud-allow-file"],
        ]) {
            const { record: error } = await submitWithoutGithub(extra);
            expect(error).toBeInstanceOf(ValueError);
            expect(String(error.message)).toMatch(new RegExp(`^${flag}.*confirms acme/app is private`));
            expect(remoteBranch()).toBe("");
        }
    });
    it("access that cannot reach the repository starts the replay on push", async () => {
        const access = () => ({ source: "GH_TOKEN", token: "t" });
        for (const [name, api] of [
            [
                "cannot read",
                () => {
                    throw new CommandError("x", 404);
                },
            ],
            ["cannot push to", () => ({ permissions: { push: false } })],
        ]) {
            const { record, api: called, err, } = await submitWithoutGithub([], {
                execution: randomUUID(),
                mocks: { githubAccess: access, api },
            });
            expect(record.startedOnPush, name).toBe(true);
            expect(err).toContain(`GitHub access from GH_TOKEN ${name} acme/app`);
            expect(called.mock.calls.some((call) => String(call[1]).endsWith("dispatches"))).toBe(false);
        }
    });
    it("a github outage stops the replay instead of starting it on push", async () => {
        const { record: error } = await submitWithoutGithub([], {
            mocks: {
                githubAccess: () => ({ source: "GH_TOKEN", token: "t" }),
                api: () => {
                    throw new CommandError("x", 503);
                },
            },
        });
        expect(error).toBeInstanceOf(ValueError);
        expect(error).not.toBeInstanceOf(GithubUnreachable);
        expect(String(error.message)).toMatch(/cannot read acme\/app \(HTTP 503\)/);
        expect(remoteBranch()).toBe("");
    });
    it("resuming a replay whose push never happened does not report a run", async () => {
        await submitWithoutGithub();
        const file = path.join(stateDirectory(fixture.root), `${ID}.json`);
        writeFileSync(file, JSON.stringify({
            ...JSON.parse(readFileSync(file, "utf8")),
            state: "prepared",
        }));
        const { record: error, err } = await submitWithoutGithub();
        expect(String(error.message)).toMatch(/Submission stopped before dispatch/);
        expect(err).not.toContain("this command gets no updates");
    });
    it("a comment inside the on block does not hide its push trigger", async () => {
        const workflow = PUSH_WORKFLOW.replace("  push:\n", "# replay without GitHub access\n  push:\n");
        expect(startsOnPush(workflow)).toBe(true);
        fixture.write(WORKFLOW_PATH, workflow);
        await updateWorkflow(fixture.root, WORKFLOW_PATH);
        const text = fixture.read(WORKFLOW_PATH);
        expect(text.split("  push:").length - 1).toBe(1);
    });
    it("update indents new keys past comment lines in their block", async () => {
        const workflow = WORKFLOW_TEXT.replace("on: workflow_dispatch", "on:\n# triggers\n  workflow_dispatch:").replace("jobs:\n", "permissions:\n# scopes\n  contents: read\njobs:\n# the job\n");
        fixture.write(WORKFLOW_PATH, workflow);
        await updateWorkflow(fixture.root, WORKFLOW_PATH);
        const text = fixture.read(WORKFLOW_PATH);
        expect(text).toContain("\n  push:\n    branches:\n");
        expect(text).toContain("\n  id-token: write\n");
        expect(text).toContain(`\n    if: ${JSON.stringify(PUSH_CONDITION)}\n`);
        expect(text).not.toMatch(/\n(push|id-token|if):/);
    });
    it("the push run condition only applies to replay branches", () => {
        expect(PUSH_CONDITION).toContain(`!startsWith(github.ref_name, '${PREFIX}')`);
    });
    it("update leaves an existing push trigger for the user to extend", async () => {
        for (const trigger of ["  push:\n    tags:\n      - v*\n", "  push:\n"]) {
            fixture.write(WORKFLOW_PATH, `${KEY_WORKFLOW.replace("permissions:\n", `${trigger}permissions:\n`)}# bitfab-replay/ mentioned here\n`);
            const result = await updateWorkflow(fixture.root, WORKFLOW_PATH);
            const text = fixture.read(WORKFLOW_PATH);
            expect(text.split("  push:").length - 1, trigger).toBe(1);
            expect(result.next.some((step) => step.includes(`${PREFIX}** in on.push.branches`)), trigger).toBe(true);
            expect(text).toContain(`if: ${JSON.stringify(PUSH_CONDITION)}`);
        }
    });
    it("with github access a workflow that starts on push is still dispatched", async () => {
        fixture.write(WORKFLOW_PATH, PUSH_WORKFLOW);
        const record = {};
        const calls = [];
        const [result] = await withLocal({
            preflight: async () => { },
            api: fixture.github(record, "", null, calls),
            localClient: () => null,
        }, () => runCli([...fixture.argv, "--cloud-detach"]));
        expect(result).not.toHaveProperty("startedOnPush");
        expect(calls.some(([suffix]) => suffix.endsWith("dispatches"))).toBe(true);
        expect(fixture.git("log", "-1", "--format=%s", result.sha)).toBe(`Bitfab replay ${ID} [skip actions]`);
    });
    it("watching a replay started on push finds its push run", async () => {
        const { record } = await submitWithoutGithub();
        const calls = [];
        const [watched] = await withLocal({ api: fixture.github(record, "", null, calls) }, () => runCli(["--cloud-status", ID]));
        expect(watched.runId).toBe(42);
        const query = calls
            .map(([suffix]) => suffix)
            .find((suffix) => suffix.includes("/runs?"));
        expect(query).toContain("event=push");
    });
    it("runner replays a snapshot started on push", async () => {
        const mark = path.join(fixture.temp, "ran");
        fixture.write("registry.mjs", `import { writeFileSync } from "node:fs"\nwriteFileSync(${JSON.stringify(mark)}, "ran")\n${registryPrinting({ testRunId: RUN, items: [] })}`);
        fixture.commit("marker");
        deps.git(fixture.root, "commit", "-q", "--allow-empty", "-F", "-", {
            input: `${PUSH_SUBJECT} ${ID}\n\n${JSON.stringify(fixture.request)}\n`,
        });
        const result = await fixture.execute(null, {
            snapshot: false,
            GITHUB_EVENT_NAME: "push",
        });
        expect(result.exitCode).toBe(0);
        expect(existsSync(mark)).toBe(true);
    });
});
describe("cloud replay keys", () => {
    it("dispatch hands the runner a one time token instead of a key", async () => {
        const { inputs, bitfab, saved, err } = await keyedDispatch();
        expect(inputs).toEqual({ request: "-", key_id: TOKEN });
        expect(bitfab).toHaveBeenCalledTimes(1);
        expect(bitfab).toHaveBeenCalledWith(LOCAL_CLIENT, "replay/cloudKey", {
            payload: {
                executionId: ID,
                repository: "acme/app",
                ref: `refs/heads/${PREFIX}${ID}`,
                workflow: "bitfab-replay.yml",
            },
        });
        expect(JSON.stringify(saved)).not.toContain("bf_local_key");
        expect(JSON.stringify(inputs)).not.toContain("bf_local_key");
        expect(err).toContain(`one-time token that only bitfab-replay.yml running on ${PREFIX}${ID} in acme/app can use`);
    });
    it("dispatch to a workflow that cannot prove its run sends no token", async () => {
        fixture.write(WORKFLOW_PATH, KEY_WORKFLOW.replace("permissions:\n  id-token: write\n", ""));
        const record = {};
        const calls = [];
        const { stderr } = await withLocal({
            preflight: async () => { },
            api: fixture.github(record, "", null, calls),
            localClient: () => {
                throw new Error("probed the local key");
            },
        }, () => capture(() => runCli([...fixture.argv, "--cloud-detach"])));
        const dispatch = calls.find(([suffix]) => suffix.endsWith("dispatches"))?.[1];
        expect(dispatch.payload.inputs).toEqual({ request: "-" });
        expect(stderr).toContain("does not grant id-token: write");
        expect(stderr).toContain("run bitfab-replay --cloud-update");
    });
    it("dispatch falls back to the workflow secret when no token is issued", async () => {
        for (const [extra, message] of [
            [{ client: null }, "resolved no API key on this machine"],
            [
                {
                    failure: new CommandError("Bitfab POST replay/cloudKey failed (HTTP 404)", 404),
                },
                "replay/cloudKey failed (HTTP 404)",
            ],
            [{ issued: { token: "bf_not_a_token" } }, "issued no replay token"],
        ]) {
            rmSync(path.join(stateDirectory(fixture.root), `${ID}.json`), {
                force: true,
            });
            REAL_COMMAND([
                "git",
                "--git-dir",
                fixture.remote,
                "update-ref",
                "-d",
                `refs/heads/${PREFIX}${ID}`,
            ]);
            const { inputs, err } = await keyedDispatch(extra);
            expect(inputs, message).toEqual({ request: "-" });
            expect(err).toContain(message);
            expect(err).toContain("uses the workflow's BITFAB_API_KEY secret");
        }
    });
    it("dispatch to a workflow without the key input says how to add it", async () => {
        const record = {};
        const calls = [];
        const { stderr } = await withLocal({
            preflight: async () => { },
            api: fixture.github(record, "", null, calls),
            localClient: () => {
                throw new Error("probed the local key");
            },
        }, () => capture(() => runCli([...fixture.argv, "--cloud-detach"])));
        expect(stderr).toContain("takes no key_id input");
        expect(stderr).toContain("run bitfab-replay --cloud-update");
    });
    it("local client is read from the replay command with the same arguments", async () => {
        const mark = path.join(fixture.temp, "probe-argv");
        fixture.write("probe.mjs", 'import { writeFileSync } from "node:fs"\n' +
            "writeFileSync(process.env.MARK, JSON.stringify(process.argv.slice(2)))\n" +
            'console.log("registry noise")\n' +
            'if (process.argv.at(-1) === "--print-api-key") {\n' +
            '  console.log("@@bitfab:api-key " + process.env.PROBE_LINE)\n' +
            "}\n" +
            'process.exit(Number(process.env.PROBE_EXIT ?? "0"))\n');
        const request = { cwd: ".", args: fixture.replay };
        const fallback = { apiKey: "bf_key", serviceUrl: "https://bitfab.ai" };
        for (const [line, code, expected] of [
            ['{"apiKey": "bf_key"}', "0", fallback],
            ['{"apiKey": "bf_key", "serviceUrl": null}', "0", fallback],
            [
                '{"apiKey": "bf_key", "serviceUrl": "http://localhost:3012/"}',
                "0",
                { apiKey: "bf_key", serviceUrl: "http://localhost:3012" },
            ],
            ['{"apiKey": null}', "0", null],
            ['{"apiKey": "  "}', "0", null],
            ['["bf_key"]', "0", null],
            ["not json", "0", null],
            ['{"apiKey": "bf_key"}', "1", null],
        ]) {
            await withEnv({
                [REPLAY_COMMAND_ENV]: JSON.stringify([process.execPath, "probe.mjs"]),
                MARK: mark,
                PROBE_LINE: line,
                PROBE_EXIT: code,
            }, () => {
                expect(localClient(fixture.root, request), `${line} ${code}`).toEqual(expected);
                expect(JSON.parse(readFileSync(mark, "utf8"))).toEqual([
                    ...fixture.replay,
                    "--print-api-key",
                ]);
            });
        }
    });
    it("the key secret is deleted once the replay step starts", async () => {
        const name = `BITFAB_REPLAY_KEY_${KEY_ID}`;
        const record = fixture.record({
            runId: 42,
            keySecret: { name, environment: "bitfab-replay" },
        });
        const steps = [
            { name: "Set up job", status: "completed" },
        ];
        const gh = [];
        stub("api", async () => ({ jobs: [{ id: 7, name: "replay", steps }] }));
        stub("command", fakeGh(gh));
        stub("githubAccess", () => ({
            source: "the GitHub CLI",
            token: "gh-token",
        }));
        await capture(async () => {
            const shown = new Set();
            await reportSteps(record, shown);
            expect(gh).toEqual([]);
            steps.push({
                name: "Run node registry.mjs --cloud-execute",
                status: "in_progress",
            });
            await reportSteps(record, shown);
            await reportSteps(record, shown);
        });
        expect(gh.map(([args]) => args)).toEqual([
            [
                "gh",
                "secret",
                "delete",
                name,
                "--repo",
                "acme/app",
                "--env",
                "bitfab-replay",
            ],
        ]);
        expect(record.keySecret.removed).toBe(true);
    });
    it("cleanup deletes a key secret the run never reached", async () => {
        const name = `BITFAB_REPLAY_KEY_${KEY_ID}`;
        for (const [failure, removed, message] of [
            [null, true, ""],
            [new CommandError("gone", 404), true, ""],
            [new CommandError("forbidden", 403), false, "delete it at"],
        ]) {
            const record = fixture.record({
                state: "prepared",
                keySecret: { name, environment: null },
            });
            const gh = [];
            stub("command", fakeGh(gh, failure));
            stub("githubAccess", () => ({ source: "the GitHub CLI", token: "t" }));
            try {
                const { stderr } = await capture(() => cleanup(fixture.root, record));
                expect(gh[0][0]).toEqual([
                    "gh",
                    "secret",
                    "delete",
                    name,
                    "--repo",
                    "acme/app",
                ]);
                expect(record.keySecret.removed ?? false, String(failure)).toBe(removed);
                expect(stderr).toContain(message);
            }
            finally {
                restoreDeps();
            }
        }
    });
    it("runner replays with a key an older workflow passes through a secret", async () => {
        const mark = keyRegistry();
        await fixture.execute(null, {
            MARK: mark,
            BITFAB_REPLAY_BITFAB_API_KEY: "bf_dispatcher",
        });
        expect(readFileSync(mark, "utf8")).toBe("bf_dispatcher");
        expect(fixture.runnerOutput).toContain("API key of the person who started this run");
        await fixture.execute(null, {
            MARK: mark,
            BITFAB_REPLAY_BITFAB_API_KEY: "",
        });
        expect(fixture.runnerOutput).not.toContain("API key of the person who started this run");
    });
    it("runner warns when the workflow needs cloud update", async () => {
        const mark = keyRegistry();
        await fixture.execute(null, {
            MARK: mark,
            BITFAB_REPLAY_BITFAB_API_KEY: "",
        });
        expect(fixture.runnerOutput).toContain("::warning title=Bitfab replay::This workflow still sets BITFAB_REPLAY_BITFAB_API_KEY");
        expect(fixture.runnerOutput).toContain("does not grant id-token: write");
        expect(fixture.runnerOutput).toContain("bitfab-replay --cloud-update");
        await fixture.execute(null, {
            MARK: mark,
            ACTIONS_ID_TOKEN_REQUEST_URL: "https://token.example/id",
            BITFAB_REPLAY_BITFAB_API_KEY: undefined,
        });
        expect(fixture.runnerOutput).not.toContain("--cloud-update");
    });
    it("runner trades the token for a key and turns it off afterwards", async () => {
        const mark = keyRegistry();
        const bitfab = vi.fn(() => ({ apiKey: "bf_minted" }));
        await executeWithToken(mark, bitfab);
        expect(readFileSync(mark, "utf8")).toBe("bf_minted");
        expect(bitfab.mock.calls).toEqual([
            [
                { serviceUrl: RUNNER_CLIENT.serviceUrl },
                "replay/cloudKey/redeem",
                { payload: { token: TOKEN, oidcToken: OIDC_TOKEN } },
            ],
            [
                { apiKey: "bf_minted", serviceUrl: RUNNER_CLIENT.serviceUrl },
                "replay/cloudKey",
                { method: "DELETE" },
            ],
        ]);
        expect(fixture.runnerOutput).toContain("::add-mask::bf_minted");
        expect(fixture.runnerOutput).toContain("Replaying as the person who started this run");
    });
    it("runner uses the workflow secret when the token cannot be traded", async () => {
        const mark = keyRegistry();
        for (const [client, failure, identity, message] of [
            [null, null, true, "resolved no API key on the runner"],
            [RUNNER_CLIENT, null, false, "does not grant id-token: write"],
            [
                RUNNER_CLIENT,
                new CommandError("Bitfab POST replay/cloudKey/redeem failed (HTTP 400): belongs to another GitHub run", 400),
                true,
                "belongs to another GitHub run",
            ],
        ]) {
            const bitfab = vi.fn(() => {
                if (failure !== null) {
                    throw failure;
                }
                return {};
            });
            await executeWithToken(mark, bitfab, { client, identity });
            expect(readFileSync(mark, "utf8"), message).toBe("");
            expect(fixture.runnerOutput).toContain("::warning title=Bitfab replay::");
            expect(fixture.runnerOutput).toContain(message);
            expect(fixture.runnerOutput).toContain("BITFAB_API_KEY secret");
        }
    });
});
describe("github run identity", () => {
    it("asks github for a token meant for bitfab", async () => {
        const urlopen = stub("urlopen", async () => Buffer.from(JSON.stringify({ value: OIDC_TOKEN })));
        await withEnv({
            ACTIONS_ID_TOKEN_REQUEST_URL: "https://token.example/id?api-version=2",
            ACTIONS_ID_TOKEN_REQUEST_TOKEN: "request-bearer",
        }, async () => {
            expect(await githubRunIdentity()).toBe(OIDC_TOKEN);
        });
        const request = urlopen.mock.calls[0][0];
        expect(request.url).toBe("https://token.example/id?api-version=2&audience=bitfab-cloud-replay");
        expect(request.headers.Authorization).toBe("Bearer request-bearer");
    });
    it("says the workflow must grant id token when github offers none", async () => {
        await withEnv({ ACTIONS_ID_TOKEN_REQUEST_URL: "", ACTIONS_ID_TOKEN_REQUEST_TOKEN: "" }, async () => {
            const attempt = githubRunIdentity();
            await expect(attempt).rejects.toThrow(CommandError);
            await expect(attempt).rejects.toThrow(/does not grant id-token: write/);
        });
    });
});
